import {  Card } from "antd";
import Meta from "antd/es/card/Meta";
import { StarButton } from "./StarButton";
import { useDispatch } from "react-redux";
import { setFavorite } from "../slices/dataSlilce";


const PokemonCard = ({name, url, abilities, types, id, favorite,index}) =>{
    // console.log(url)
    const typeString = types.map(type=>type.type.name).join(", ")
    // console.log(typeString)
    const dispatch = useDispatch()
    // const favorite = useSelector(state => state.favorite)
    // if(pokemon.id === 1 || pokemon.id === 2 ||pokemon.id === 3)
    // console.log(id,name,pokemon.favorite)
    
    // console.log(name[0].toUpperCase())
    name =  name[0].toUpperCase() + name.slice(1)
    // name = name.filter((letter,index)=>index=0 ? letter.toUpperCase() :  letter)
    const handleOnFavorite = () =>{

        console.log(id)
        dispatch(setFavorite({pokemonId:id}))

        // dispatch(setFavorite({pokemonId:id}))
        // console.log(pokemon)

    }
/* <StarButton isFavorite={favorite} onClick={()=>handleOnFavorite}/> */

    return (
        <>
        
        <Card
            id={id}
            title={ <><span style={{fontWeight:"800"}}>{index}</span> <span>{name}</span>   </>  } 
            
            cover={<img className="img-pokemon" src={url} alt="Ditto"/>}
            // extra={<Button icon={favorite? <StarFilled/>: <StarOutlined/>} onClick={handleOnFavorite} ></Button>}
            extra={ <StarButton isFavorite={favorite}  onClick={handleOnFavorite}></StarButton> }
        >
        
        <Meta style={{paddingBottom:"10px"}} title="Habilidades" description={abilities}/>
        <Meta title="Tipo" description={typeString}/>
        </Card>
        </>
    )
}

export default PokemonCard




