// import logo from './logo.svg';
import './App.css';
import { PokemonList } from './components/PokemonList';
import Searcher from './components/Searcher';
import { Col, Spin } from 'antd';
import logo from './statics/logo.svg'
import { useEffect } from 'react';
import PokemonCard from './components/PokemonCard';
import { shallowEqual, useDispatch, useSelector } from 'react-redux';
import { fetchPokemonsWithDetails } from './slices/dataSlilce';
import { useState, useMemo } from 'react';

function App() {

  // npm install immutable@4
//  npm install redux-immutable para que funcione debe ser immtable 4

  // const [pokemons, setPokemons] = useState()
  const [searchApp, setSearchApp] = useState()

  // const pokemons = useSelector(state => state.get('data')).get('pokemons').toJS();
  //shallowEqual compara objetos y regresa booleano para que la comparación estricta no compare referencias con objetos
  // const pokemons = useSelector(state => state.getIn(['data','pokemons'],shallowEqual)).toJS();
  const pokemonsAll =  useSelector(state => state.data.pokemons,shallowEqual);
  
  const loading = useSelector(state => state.ui.loading)
  // const loading = false 
  const dispatch = useDispatch()

    useEffect(()=>{
      
      dispatch(fetchPokemonsWithDetails())
      
    },[dispatch])

  const filteredPokemons = useMemo(() => {
    if (!searchApp) return pokemonsAll

    return pokemonsAll.filter(pokemon =>
      pokemon.name.toLowerCase().includes(searchApp.toLowerCase())
    )
  }, [searchApp, pokemonsAll])
    
    
  console.log(filteredPokemons)
  // const pokemons = Array(10).fill('');
// console.log(pokemons)
  return (
    <div className="App">
      <div className='header'>
        <Col col span={8} offset={6}>
          <img className='imgPokedux' src={logo} alt='pokedux'/>
        </Col>
        <Col className='Searcher'
                span={16} 
                offset={6}>
              <Searcher searc={searchApp} setSearch={setSearchApp}/>
              
              </Col>
      </div>
    
      {loading 
      ? 
          <Col offset={10} >
          <Spin spinning size='large' />

          </Col>
      : 
        <PokemonList pokemons={filteredPokemons} >
          { (pokemon,index) => {
            // console.log(pokemon.favorite)
          return  <PokemonCard
              key={pokemon.name}
              index={index+1}
              pokemon={pokemon}
              name={pokemon.name}
              id={pokemon.id}
              url={pokemon.sprites?.front_default}
              favorite={pokemon.favorite}
              abilities={pokemon.abilities?.map(ability=> ability?.ability.name).join(", ")}
              types={pokemon.types}
            
            />
          }}
        </PokemonList>
      }
      
    </div>
  );
}


export default App;


