import { Input } from 'antd';

const Searcher = ({search, setSearch}) =>{

    const handleSearch = (event) =>{
        // setSearch(search => search = event.target.value)
        setSearch(search => search = event.target.value)
        console.log(search)

    }
    return (
        <>
        <Input.Search className='Searcher' onChange={handleSearch} value={search} placeholder='Buscar...' />
        </>
    )
}

export default Searcher