import axios from "axios";

const getPokemon = async () =>{
    return axios.get('https://pokeapi.co/api/v2/pokemon?limit=100')
            .then(res=>res.data.results)
            .catch(e=>console.log(e))
}

const  getPokemonDetailed = async (pokemonList) => {
    // console.log(pokemonList)
    const response = await Promise.all(pokemonList.map(
        async pokemon=> {
                try{
                    // console.log(pokemon.url)
                    const response = await  axios.get(pokemon.url);
                    // pokemon.url = await response.json().sprites.front_default;
                    // const respuesta = await response.json()
                    // console.log(response)
                    // pokemon.url = response.data.sprites.front_default
                    // console.log(pokemon.url)
                    return  response.data
                }catch(e){
                    console.log(e)
                }
            }
                )
            )
            // console.log(response)
    return response
}

export  {getPokemon, getPokemonDetailed};