import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import { getPokemon, getPokemonDetailed } from "../api";
import { setLoading } from "./uiSlice";
// import { setFavorite } from "../actions";
//aqui no usamos immutable porque redux usa imma que se encarga de la inmutablidad todo el tiempo
const initialState = {
    pokemons: [],
}

export const fetchPokemonsWithDetails = createAsyncThunk(
    'data/fetchPokemonsWithDetails',
    async (_, {dispatch}) => {
        
        //dispath loader
        
        //fetch
        dispatch(setLoading(true))
        const pokemonRes = await getPokemon();
        console.log(pokemonRes)
        const pokemonsDetailed = await getPokemonDetailed(pokemonRes);
        dispatch(setPokemons(pokemonsDetailed));
        dispatch(setLoading(false))

        //dispatch loadder
    }
    
);


export const dataSlice = createSlice({
    name:'data',
    initialState,
    reducers: {
        setPokemons: (state, action) =>{
            // 'data/setPokemon' esta es la convencion
            state.pokemons = action.payload
        },
        setFavorite: (state,action) =>{
            
            const currentPokemonIndex = state.pokemons.findIndex(
                pokemon=> pokemon.id === action.payload.pokemonId
            )
            console.log(state)
            
            // console.log("action ",action,state.pokemons[currentPokemonIndex].favorite)
            if(currentPokemonIndex >= 0){
                    const isFavorite = state.pokemons[currentPokemonIndex]?.favorite;
                    console.log(isFavorite)
                    state.pokemons[currentPokemonIndex].favorite= !isFavorite;
                    
                }


        
        },
    },
})

export const {setPokemons, setFavorite } = dataSlice.actions;
console.log(dataSlice)
export default dataSlice.reducer;